One pass, two trackers. O(n) time, O(1) memory.

```python
def second_largest(nums):
    first = second = float("-inf")
    for x in nums:
        if x > first:
            first, second = x, first
        elif first > x > second:
            second = x
    return second

print(second_largest([3, 9, 4]), second_largest([5, 5, 3]), second_largest([-2, -7]))
```

A stack: the last bracket opened is the first that must close.

```python
def balanced(s):
    pairs = {")": "(", "]": "[", "}": "{"}
    stack = []
    for ch in s:
        if ch in "([{":
            stack.append(ch)
        elif ch in pairs:
            if not stack or stack.pop() != pairs[ch]:
                return False
    return not stack

print(balanced("{[()]}"), balanced("([)]"), balanced("(("), balanced(""))
```

