Validate first, then mutate. That ordering is the whole lesson.

```python
class BankAccount:
    def __init__(self, balance=0):
        self.balance = balance

    def deposit(self, amount):
        if amount <= 0:
            raise ValueError("amount must be positive")
        self.balance += amount

    def withdraw(self, amount):
        if amount <= 0:
            raise ValueError("amount must be positive")
        if amount > self.balance:
            raise ValueError("insufficient funds")
        self.balance -= amount


def test_rules():
    a = BankAccount()
    a.deposit(100)
    a.withdraw(30)
    assert a.balance == 70
    try:
        a.withdraw(100)
        raise AssertionError("expected ValueError")
    except ValueError:
        pass
    assert a.balance == 70

test_rules()
print("all tests passed")
```

The loop runs thousands of times a second and only *checks* whether it's time to toggle.

```arduino
const int BLINK_LED = 13, BUTTON_LED = 12, BUTTON = 2;
unsigned long lastToggle = 0;
bool blinkOn = false;

void setup() {
  pinMode(BLINK_LED, OUTPUT);
  pinMode(BUTTON_LED, OUTPUT);
  pinMode(BUTTON, INPUT_PULLUP);   // pressed = LOW
}

void loop() {
  unsigned long now = millis();
  if (now - lastToggle >= 500) {   // subtraction stays correct when millis() wraps
    lastToggle = now;
    blinkOn = !blinkOn;
    digitalWrite(BLINK_LED, blinkOn);
  }
  digitalWrite(BUTTON_LED, digitalRead(BUTTON) == LOW);
}
```
